def icon(name, size=18, cls=""):
    paths = ICON_PATHS.get(name, ICON_PATHS["sparkles"])
    css = f"icon {escape(cls)}".strip()
    return Markup(
        f'<svg class="{css}" width="{int(size)}" height="{int(size)}" viewBox="0 0 24 24" fill="none" '
        f'stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" '
        f'aria-hidden="true" focusable="false">{paths}</svg>'
    )
